"""Reference states of CMA-ES from pycma, for heuresis's check of the CMA-ES update.

For each of a few generations of pycma (its own samples, from its own seed, on an ellipsoid), this records the
state before `tell` (mean, sigma, C, the paths p_c and p_sigma, and the inverse square root of C that pycma uses,
from its possibly lazy eigendecomposition), the lambda points told and their values, and the state after `tell`.
heuresis's check loads each state before, applies its own update to the same points, and compares the state after.
The constants (weights, c_c, c_sigma, c_1, c_mu, d_sigma, and pycma's E||N(0, I)||) are pycma's, read from the
instance, since pycma 4 departs from the tutorial's Table 1 in c_sigma, c_mu and d_sigma; the update rules are the
tutorial's (Hansen 2016, arXiv:1604.00772), which pycma's follow apart from the details stated in the check.

Two runs: active CMA off (the update without negative weights) and on.

Run with pycma installed (pip install cma); writes cma_fixture.hpp beside this script.
"""

import datetime
import os

import numpy as np
import cma
from cma import sigma_adaptation
from cma.utilities.math import Mh

N = 6
GENERATIONS = 8


def ellipsoid(x):
    return float(sum(10 ** (6.0 * i / (N - 1)) * x[i] ** 2 for i in range(N)))


def state(es):
    inv = np.column_stack([es.sm.transform_inverse(e) for e in np.eye(N)])
    return {
        "mean": np.array(es.mean, dtype=float),
        "sigma": float(es.sigma),
        "C": np.array(es.sm.C, dtype=float),
        "pc": np.array(es.pc, dtype=float),
        "ps": np.array(getattr(es.adapt_sigma, "ps", None) if getattr(es.adapt_sigma, "ps", None) is not None else np.zeros(N), dtype=float),
        "inv": inv,
    }


def run(active):
    es = cma.CMAEvolutionStrategy(N * [1.0], 0.5, {"verbose": -9, "seed": 20261105, "CMA_active": active})
    if not active:
        assert all(w >= 0 for w in es.sp.weights), "active off: no negative weights"
    params = {
        "lambda": es.sp.popsize,
        "weights": list(map(float, es.sp.weights)),
        "mueff": float(es.sp.weights.mueff),
        "cc": float(es.sp.cc),
        "cs": float(es.adapt_sigma.cs),
        "c1": float(es.sp.c1),
        "cmu": float(es.sp.cmu),
        "damps": float(es.adapt_sigma.damps),
        "chiN": float(Mh.chiN(N)),
    }
    assert es.opts["CSA_dampfac"] == 1 and sigma_adaptation.csa_dampdown_fac == 1
    gens = []
    for g in range(GENERATIONS):
        X = es.ask()
        f = [ellipsoid(x) for x in X]
        before = state(es)
        if g == 0:  # pycma initialises its step-size adaptation at the first tell
            before["ps"] = np.zeros(N)
        es.tell(X, f)
        after = state(es)
        # pycma's h_sigma, from its rule (the check states it)
        cs = es.adapt_sigma.cs
        hsig = (np.sum(after["ps"] ** 2) / (1 - (1 - cs) ** (2 * es.countiter))) / N - 1 < 1 + 4.0 / (N + 1)
        gens.append({"before": before, "X": np.array(X, dtype=float), "f": f, "after": after, "hsig": bool(hsig), "countiter": es.countiter})
    return params, gens


def cpp_array(name, values):
    flat = np.asarray(values, dtype=float).ravel()
    return "inline constexpr double %s[%d] = {%s};\n" % (name, len(flat), ", ".join(repr(float(v)) for v in flat))


def emit(prefix, params, gens):
    out = "namespace %s {\n" % prefix
    out += "inline constexpr std::size_t lambda = %d;\n" % params["lambda"]
    out += "inline constexpr std::size_t generations = %d;\n" % len(gens)
    out += cpp_array("weights", params["weights"])
    out += "inline constexpr double mueff = %r, cc = %r, cs = %r, c1 = %r, cmu = %r, damps = %r, chi_n = %r;\n" % (
        params["mueff"], params["cc"], params["cs"], params["c1"], params["cmu"], params["damps"], params["chiN"])
    for key in ["mean", "sigma", "C", "pc", "ps", "inv"]:
        out += cpp_array("before_" + key, [gen["before"][key] for gen in gens])
        if key != "inv":
            out += cpp_array("after_" + key, [gen["after"][key] for gen in gens])
    out += cpp_array("points", [gen["X"] for gen in gens])
    out += cpp_array("values", [gen["f"] for gen in gens])
    out += "inline constexpr bool hsig[%d] = {%s};\n" % (len(gens), ", ".join("true" if gen["hsig"] else "false" for gen in gens))
    out += "inline constexpr std::uint64_t countiter[%d] = {%s};\n" % (len(gens), ", ".join(str(gen["countiter"]) for gen in gens))
    out += "}  // namespace %s\n" % prefix
    return out


def main():
    here = os.path.dirname(os.path.abspath(__file__))
    text = "// Generated by make_cma_fixtures.py from pycma %s (numpy %s) on %s; do not edit.\n" % (
        cma.__version__, np.__version__, datetime.date.today().isoformat())
    text += "// n = %d, an ellipsoid of condition 1e6, mean (1, ..., 1), sigma 0.5, pycma's seed 20261105.\n" % N
    text += "#pragma once\n#include <cstddef>\n#include <cstdint>\nnamespace cma_fixture {\n"
    text += "inline constexpr std::size_t n = %d;\n" % N
    for prefix, active in [("passive", False), ("active", True)]:
        params, gens = run(active)
        text += emit(prefix, params, gens)
    text += "}  // namespace cma_fixture\n"
    with open(os.path.join(here, "cma_fixture.hpp"), "w", encoding="utf-8") as fh:
        fh.write(text)


if __name__ == "__main__":
    main()
